outline_text:
{
  "title": "Ship Faster with Our API",
  "theme": "gaia",
  "paginate": true,
  "slides": [
    {
      "title": "Hook",
      "summary": "One API, five endpoints, and your integration live today; this talk is the whole getting-started path."
    },
    {
      "title": "Authentication",
      "summary": "One bearer token per workspace; create it in settings; rotate without downtime using the two-token overlap window."
    },
    {
      "title": "Five Endpoints You Need",
      "summary": "List, get, create, update, delete on the resource endpoint family; everything else is a parameter on these five."
    },
    {
      "title": "Rate Limits",
      "summary": "600 requests per minute per token; burst to 900 for ten seconds; the headers tell you exactly when the window resets."
    },
    {
      "title": "Pagination",
      "summary": "Cursor-based, not offsets: pass the returned cursor, stop at the empty page; stable under concurrent writes."
    },
    {
      "title": "Error Handling",
      "summary": "Every error is JSON with a code, a message and a doc link; the 429 response includes the retry-after seconds."
    },
    {
      "title": "Webhooks",
      "summary": "Subscribe once, get events pushed; deliveries retry for 24 hours; verify signatures with the shared secret header."
    },
    {
      "title": "SDKs and Examples",
      "summary": "Official SDKs in TypeScript, Python and Go; copy-paste examples for every endpoint in the docs."
    },
    {
      "title": "Call to Action",
      "summary": "Free tier, no card, docs at example.com/docs; the QR code takes you straight to a running key."
    }
  ]
}
